<div class="property-detail-header"><div><a href="<?= $e($returnUrl) ?>">← Voltar para o cadastro</a><h1>Contato pelo WhatsApp</h1><p><?= $e($contact['name']) ?></p></div></div>
<?php if(empty($contact['phone'])): ?><div class="alert alert-info" role="status">Este contato ainda não tem telefone cadastrado. Informe um número com DDD para preparar a conversa. O número informado aqui será usado somente nesta abertura.</div><?php endif; ?>
<form class="whatsapp-composer" onsubmit="return false"><label for="whatsapp-rule">Régua do contato<select id="whatsapp-rule" required><option value="">Selecione uma régua</option><?php foreach($rules as $rule): ?><option value="<?= $e($rule) ?>"><?= $e($rule) ?></option><?php endforeach; ?></select></label>
<label for="whatsapp-phone">Telefone com DDD<input id="whatsapp-phone" type="tel" value="<?= $e($contact['phone']??'') ?>" placeholder="(21) 99999-8888" autocomplete="tel" aria-describedby="whatsapp-phone-help"><small id="whatsapp-phone-help">Se já estiver cadastrado, será usado aqui. Caso contrário, informe o número para esta abertura. Para números brasileiros, o link incluirá 55.</small></label>
<div class="whatsapp-context"><strong>Imóveis no contexto</strong><ul><?php if($properties): foreach($properties as $property): ?><li><a href="/properties/<?= (int)($property['property_id']??$property['id']) ?>"><?= $e($property['code']) ?></a> — <?= $e($property['title']) ?></li><?php endforeach; else: ?><li>Nenhum imóvel vinculado.</li><?php endif; ?></ul></div>
<label for="whatsapp-message">Mensagem inicial (editável)<textarea id="whatsapp-message" rows="7" maxlength="4000" required placeholder="Selecione uma régua para montar uma sugestão."></textarea></label>
<p class="whatsapp-guidance">Ao abrir o WhatsApp Desktop, confira a conversa e conclua o envio no aplicativo. O CRM não consegue ler o status do WhatsApp. Depois, volte aqui e informe o resultado.</p><div class="property-form-actions"><a id="whatsapp-open" href="#" role="button" aria-disabled="true" class="secondary">Abrir WhatsApp Desktop</a></div></form>
<section class="whatsapp-result"><h2>Registrar resultado após voltar ao CRM</h2><p>O envio só será registrado como confirmado quando você declarar que enviou.</p><?php foreach(['confirmed'=>'Confirmado pelo corretor','not_sent'=>'Não enviado','cancelled'=>'Cancelar contato'] as $key=>$label): ?><form method="post" action="<?= $e($action) ?>" class="whatsapp-result-form"><?= $csrfField ?><input type="hidden" name="result" value="<?= $e($key) ?>"><input type="hidden" name="rule" class="wa-hidden-rule"><input type="hidden" name="message" class="wa-hidden-message"><button type="submit" class="<?= $key==='confirmed'?'':'outline secondary' ?>" onclick="return syncWhatsAppResult(this.form)"><?= $e($label) ?></button></form><?php endforeach; ?></section>
<?php if($history): ?><section class="whatsapp-history"><h2>Histórico de WhatsApp</h2><ol><?php foreach($history as $item): ?><li><div><strong><?= $e($item['rule']) ?> · <?= $e($item['result']) ?></strong><small><?= $e($item['created_at']) ?> · <?= $e($item['user_name']??'Usuário removido') ?></small></div><p><?= nl2br($e($item['message'])) ?></p></li><?php endforeach; ?></ol></section><?php endif; ?>
<script>
(()=>{const name=<?= json_encode($contact['name'],JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;const props=<?= json_encode(array_map(static fn($p)=>$p['code'].' — '.$p['title'],$properties),JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;const select=document.getElementById('whatsapp-rule'),message=document.getElementById('whatsapp-message'),phone=document.getElementById('whatsapp-phone'),open=document.getElementById('whatsapp-open');const templates={'1º contato':`Olá, ${name}! Tudo bem? Sou corretor(a) da imobiliária e estou entrando em contato sobre seu interesse. Como posso ajudar?`,'Pós-visita':`Olá, ${name}! Gostaria de saber como foi sua visita${props.length?' ao imóvel '+props[0]:''}. O que achou?`,'Nova oportunidade':`Olá, ${name}! Encontrei uma nova oportunidade${props.length?' relacionada ao imóvel '+props[0]:''} e gostaria de compartilhar com você. Podemos conversar?`,'Follow-up':`Olá, ${name}! Estou retomando nosso contato para saber se você gostaria de avançar na busca por um imóvel${props.length?' como '+props.join(', '):''}.`,'Pós-fechamento de contrato':`Olá, ${name}! Passando para saber como está tudo após a assinatura do contrato. Conte comigo se precisar de alguma coisa.`};select.addEventListener('change',()=>{if(select.value)message.value=templates[select.value]||'';update();});[message,phone].forEach(el=>el.addEventListener('input',update));function update(){const digits=phone.value.replace(/\D/g,'');const intl=digits.startsWith('55')?digits:'55'+digits;const valid=digits.length>=10&&digits.length<=13;open.href=valid?'https://wa.me/'+intl+'?text='+encodeURIComponent(message.value):'#';open.setAttribute('aria-disabled',String(!valid||!select.value||!message.value.trim()));}open.addEventListener('click',e=>{if(open.getAttribute('aria-disabled')==='true'){e.preventDefault();if(!phone.value.trim())alert('Informe um número de telefone com DDD antes de abrir o WhatsApp.');else if(!select.value)alert('Selecione a régua do contato e revise a mensagem.');return;}open.target='_blank';});window.syncWhatsAppResult=form=>{if(!select.value){alert('Selecione a régua do contato.');return false;}if(!message.value.trim()){alert('Escreva a mensagem que será registrada no histórico.');return false;}form.querySelector('.wa-hidden-rule').value=select.value;form.querySelector('.wa-hidden-message').value=message.value;return true;};update();})();
</script>
